css:
.undo-action-container {
  display: flex;
  justify-content: center;
  align-items: center;
  width: 100%;
  font-family:
    ui-sans-serif,
    system-ui,
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    Roboto,
    sans-serif;
}

.undo-checkbox {
  display: none;
}

.undo-button {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px 24px;
  background-color: #ef4444;
  border-radius: 9999px;
  cursor: pointer;
  user-select: none;
  overflow: hidden;
  transition: all 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.15);
}

.undo-button:hover {
  filter: brightness(1.05);
}

.undo-button:active {
  transform: scale(0.98);
}

.undo-checkbox:checked ~ .undo-button {
  background-color: rgba(239, 68, 68, 0.15);
  padding: 8px 12px 8px 8px;
}

.undo-icon-wrapper {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 0;
  height: 36px;
  background-color: #ef4444;
  border-radius: 9999px;
  opacity: 0;
  filter: blur(2px);
  transform: scale(0.5);
  transition: all 0.35s cubic-bezier(0.175, 0.885, 0.32, 1.15);
  overflow: hidden;
}

.undo-icon {
  width: 20px;
  height: 20px;
  color: #ffffff;
  flex-shrink: 0;
}

.undo-checkbox:checked ~ .undo-button .undo-icon-wrapper {
  width: 36px;
  opacity: 1;
  filter: blur(0px);
  transform: scale(1);
}

.label-wrapper {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
  font-weight: 500;
  height: 28px;
}

.label-delete {
  color: #fafafa;
  white-space: nowrap;
  transition:
    opacity 0.25s ease,
    transform 0.25s ease,
    filter 0.25s ease;
}

.label-cancel {
  position: absolute;
  color: #ef4444;
  white-space: nowrap;
  opacity: 0;
  transform: translateY(10px) scale(0.85);
  filter: blur(2px);
  transition:
    opacity 0.3s ease,
    transform 0.3s ease,
    filter 0.3s ease;
}

.undo-checkbox:checked ~ .undo-button .label-delete {
  opacity: 0;
  transform: translateY(-10px) scale(0.85);
  filter: blur(2px);
  pointer-events: none;
  position: absolute;
}

.undo-checkbox:checked ~ .undo-button .label-cancel {
  opacity: 1;
  transform: translateY(0) scale(1);
  filter: blur(0px);
  position: relative;
}

.timer-wrapper {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 0;
  height: 32px;
  background-color: #ef4444;
  border-radius: 9999px;
  opacity: 0;
  filter: blur(2px);
  transform: scale(0.5);
  transition: all 0.35s cubic-bezier(0.175, 0.885, 0.32, 1.15);
  overflow: hidden;
}

.undo-checkbox:checked ~ .undo-button .timer-wrapper {
  width: 42px;
  opacity: 1;
  filter: blur(0px);
  transform: scale(1);
}

.timer-digits {
  display: flex;
  flex-direction: column;
  align-items: center;
  height: 24px;
  line-height: 24px;
  font-size: 18px;
  font-weight: 500;
  color: #ffffff;
  font-variant-numeric: tabular-nums;
  transform: translateY(0);
}

.timer-digits span {
  height: 24px;
  display: flex;
  align-items: center;
  justify-content: center;
}

@keyframes countdownStep {
  0%,
  9.2% {
    transform: translateY(0);
  }
  10%,
  19.2% {
    transform: translateY(-24px);
  }
  20%,
  29.2% {
    transform: translateY(-48px);
  }
  30%,
  39.2% {
    transform: translateY(-72px);
  }
  40%,
  49.2% {
    transform: translateY(-96px);
  }
  50%,
  59.2% {
    transform: translateY(-120px);
  }
  60%,
  69.2% {
    transform: translateY(-144px);
  }
  70%,
  79.2% {
    transform: translateY(-168px);
  }
  80%,
  89.2% {
    transform: translateY(-192px);
  }
  90%,
  100% {
    transform: translateY(-216px);
  }
}

.undo-checkbox:checked ~ .undo-button .timer-digits {
  animation: countdownStep 10s cubic-bezier(0.25, 1, 0.5, 1) forwards;
}
